 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,
 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
 * See LICENSE in the root of the software repository for the full text of the License.
 */

#ifndef HCCL_TUNER_PLUGIN_H_
#define HCCL_TUNER_PLUGIN_H_

#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include "hccl/hccl_types.h"

#ifdef __cplusplus
extern "C" {
#endif

/* ===== 通信域信息（per-comm，init 时传入）===== */

typedef struct {
    uint32_t nRanks;
    uint32_t nNpusPerServer;
    uint32_t nServers;
    uint32_t nPods;
    uint32_t nSuperPods;
    const char* commName;
    uint64_t bufferSize;
    uint32_t structSize;
} hcclTunerCommInfo_t;

/* ===== 集合通信调用信息（per-op，getCollInfo 时传入）===== */

typedef struct {
    HcclCMDType collType;
    size_t nBytes;
    HcclDataType dataType;
    uint32_t structSize;
} hcclTunerCollInfo_t;

/* ===== 算法条目（命名 cost table）===== */

typedef struct {
    const char* algName;      /* "AicpuAllReduceSoleMeshOneShot" */
    const char* engineName;   /* "aicpu" — Enrich 填充，插件只读 */
    const char* executorName; /* "sole"  — Enrich 填充，插件只读 */
    const char* templateName; /* "meshoneshot" — Enrich 填充，插件只读 */
    float cost;               /* 可修改: <0=禁用, 0=偏好, >0=覆盖, 不改=用CostModel值 */
    uint32_t structSize;
} hcclTunerAlgoEntry_t;

/* ===== Host 函数表 ===== */

typedef void (*hcclTunerLogFn_t)(int level, const char* file, int line, const char* fmt, ...);

typedef struct {
    HcclResult (*ctxCreate)(HcclComm comm, const char* ctxTag, uint64_t size, void** ctx);
    HcclResult (*ctxGet)(HcclComm comm, const char* ctxTag, void** ctx, uint64_t* size);
    HcclResult (*ctxDestroy)(HcclComm comm, const char* ctxTag);
    hcclTunerLogFn_t logFunction;
    uint32_t structSize;
} hcclTunerHostFunctions_t;

/* ===== 回调函数签名 ===== */

typedef HcclResult (*hcclTunerInit_t)(
    HcclComm comm, const hcclTunerCommInfo_t* commInfo, const hcclTunerHostFunctions_t* hostFuncs);

typedef HcclResult (*hcclTunerGetCollInfo_t)(
    HcclComm comm, const hcclTunerCollInfo_t* collInfo, hcclTunerAlgoEntry_t* algoEntries, int algoCount,
    int* matched); /* 插件设 *matched=1=命中规则并修改 cost, 0=未命中（HCCL 核心初始化为 0） */

/* ===== 函数表（V1）===== */

typedef struct {
    hcclTunerInit_t init;
    hcclTunerGetCollInfo_t getCollInfo;
    uint32_t structSize; /* HCCL 设值，plugin 据此判断缓冲区大小（ABI 兼容） */
} hcclTunerFuncs_v1_t;

/* ===== 入口符号（插件 .so 导出，符号名带版本号）===== */

extern hcclTunerFuncs_v1_t hcclTunerPlugin_v1;

/* ===== 日志级别 ===== */

#define HCCL_TUNER_LOG_ERROR 0
#define HCCL_TUNER_LOG_WARN 1
#define HCCL_TUNER_LOG_INFO 2
#define HCCL_TUNER_LOG_DEBUG 3

#ifdef __cplusplus
}
#endif

#endif /* HCCL_TUNER_PLUGIN_H_ */

/**
 * Copyright (c) 2025 Huawei Technologies Co., Ltd.
 * This program is free software, you can redistribute it and/or modify it under the terms and conditions of
 * CANN Open Software License Agreement Version 2.0 (the "License").
 * Please refer to the License for details. You may not use this file except in compliance with the License.
 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,
 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
 * See LICENSE in the root of the software repository for the full text of the License.
 */

#ifndef TUNER_SETUP_H
#define TUNER_SETUP_H

#include <cstdarg>
#include <cstddef>
#include "hccl_tuner_plugin.h"

/* HcclCMDType 定义在 hccl/hccl_types.h 中（经 hccl_tuner_plugin.h 引入），无需前向声明。 */

namespace ops_hccl {
struct TopoInfoWithNetLayerDetails;
}

#if defined(__cplusplus)
extern "C" {
#endif

/* ===== 内部 Host 函数包装（仅供 tuner_setup.cc 构造 hostFuncs 使用）===== */

HcclResult TunerCtxCreate(HcclComm comm, const char* ctxTag, uint64_t size, void** ctx);
HcclResult TunerCtxGet(HcclComm comm, const char* ctxTag, void** ctx, uint64_t* size);
HcclResult TunerCtxDestroy(HcclComm comm, const char* ctxTag);
void TunerLogFunction(int level, const char* file, int line, const char* fmt, ...);

#if defined(__cplusplus)
}
#endif

#if defined(__cplusplus)
/* ===== 对外接口 ===== */

/* 信任边界：插件 .so 在本进程内执行，拥有与 HCCL 同等权限（对标 NCCL tuner）。
 * 管理员须确保 HCCL_TUNER_PLUGIN 指向可信 .so。无路径校验（by-design）。
 * 慢调用保护（C5）：getCollInfo 连续 3 次超过 100ms 则自动禁用插件，回退 CostModel。 */

/* comm 创建时调用：dlopen 插件 + dlsym + 版本校验 + 引用计数 + 构造 hostFuncs + 调用插件 init。
 * topoInfo 用于填充 hcclTunerCommInfo_t。未配置 HCCL_TUNER_PLUGIN 或加载失败时为 no-op，返回 HCCL_SUCCESS。 */
HcclResult HcclTunerInit(HcclComm comm, const ops_hccl::TopoInfoWithNetLayerDetails* topoInfo);

/* 每次 op 时调用：构造 collInfo，调用插件 getCollInfo。
 * 插件未加载时为 no-op；不支持的算子类型（HCCL_CMD_INVALID）跳过，返回 HCCL_SUCCESS。
 * algoEntries 由调用方（Selector）提供，Enrich 已填好 3D 名，插件直接读。
 * modified 输出：true=插件命中规则并修改了 cost，false=未命中/未修改（per-call，线程安全）。 */
HcclResult HcclTunerCallGetCollInfo(
    HcclComm comm, HcclCMDType cmdType, size_t nBytes, HcclDataType dataType, hcclTunerAlgoEntry_t* algoEntries,
    int algoCount, bool* modified);

/* comm 销毁时调用：引用计数--。.so 不 dlclose（避免与在途 getCollInfo 竞争），随进程退出回收。 */
HcclResult HcclTunerDestroy(HcclComm comm);

/* 返回上次 getCollInfo 是否命中规则并修改了 cost（仅供 ST 测试在 comm destroy 后查询；
 * 生产路径应使用 HcclTunerCallGetCollInfo 的 modified 输出参数）。 */
bool HcclTunerDidModifyCost();

/* 重置 match 状态（测试 SetUp 调用，或 comm init 时调用）。 */
void HcclTunerResetMatchStatus();

/* 返回插件是否已成功加载（selector 可据此跳过 getCollInfo 调用）。 */
bool HcclTunerIsLoaded();
#endif

#endif /* TUNER_SETUP_H */

