3	 * This program is free software, you can redistribute it and/or modify it under the terms and conditions of
4	 * CANN Open Software License Agreement Version 2.0 (the "License").
5	 * Please refer to the License for details. You may not use this file except in compliance with the License.
6	 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,
7	 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
8	 * See LICENSE in the root of the software repository for the full text of the License.
9	 */
10	
11	#include "tuner_setup.h"
12	
13	#include <dlfcn.h>
14	#include <atomic>
15	#include <chrono>
16	#include <cstdlib>
17	#include <cstring>
18	#include <mutex>
19	#include <string>
20	
21	#include "alg_param.h"
22	#include "hccl_common.h"
23	#include "hccl_tuner_plugin.h"
24	
25	using ops_hccl::TopoInfoWithNetLayerDetails;
26	
27	namespace {
28	/* ===== 进程级单例状态（mutex 保护）===== */
29	constexpr int32_t LOAD_READY = 0;
30	constexpr int32_t LOAD_SUCCESS = 1;
31	constexpr int32_t LOAD_FAILED = -1;
32	
33	std::mutex g_tunerMutex;
34	int32_t g_loadStatus = LOAD_READY;
35	uint32_t g_refCount = 0;
36	void* g_libHandle = nullptr;
37	hcclTunerFuncs_v1_t g_funcs = {};
38	
39	constexpr uint32_t TUNER_COMM_NAME_MAX_LENGTH = 128;
40	constexpr const char* TUNER_CTX_PREFIX = "__tuner_";
41	constexpr uint64_t TUNER_SLOW_CALL_THRESHOLD_MS = 100;  /* getCollInfo 慢调用阈值（C5） */
42	constexpr uint32_t TUNER_SLOW_CALL_LIMIT = 3;           /* 连续慢调用上限，超过则禁用插件 */
43	constexpr uint64_t TUNER_SLOW_INIT_THRESHOLD_MS = 5000; /* init 慢调用阈值（一次性，不禁用） */
44	std::atomic<uint32_t> g_slowCallCount{0};               /* 连续慢调用计数（原子，无锁） */
45	bool g_tunerModifiedCost = false;                       /* 上次 getCollInfo 是否命中 */
46	
47	/* 读取环境变量，返回 string 便于比较。 */
48	std::string GetEnv(const char* name)
49	{
50	    const char* val = std::getenv(name);
51	    return (val != nullptr) ? std::string(val) : std::string();
52	}
53	
54	/* 首次加载插件：dlopen + dlsym + 版本校验 + 获取函数表。调用前已持锁。 */
55	bool LoadPluginLocked()
56	{
57	    if (g_loadStatus == LOAD_SUCCESS) {
58	        g_refCount++;
59	        return true;
60	    }
61	    if (g_loadStatus == LOAD_FAILED) {
62	        return false;
63	    }
64	
65	    /* LOAD_READY：首次加载 */
66	    std::string pluginPath = GetEnv("HCCL_TUNER_PLUGIN");
67	    if (pluginPath.empty() || pluginPath == "none") {
68	        g_loadStatus = LOAD_FAILED;
69	        return false;
70	    }
71	
72	    /* 信任边界：插件 .so 在本进程内执行，拥有与 HCCL 同等权限（对标 NCCL tuner）。
73	     * 管理员须确保 HCCL_TUNER_PLUGIN 指向可信 .so。无路径校验（by-design）。 */
74	    void* handle = dlopen(pluginPath.c_str(), RTLD_NOW | RTLD_LOCAL);
75	    if (handle == nullptr) {
76	        HCCL_WARNING("[Tuner] dlopen failed, path[%s], err[%s].", pluginPath.c_str(), dlerror());
77	        g_loadStatus = LOAD_FAILED;
78	        return false;
79	    }
80	
81	    auto* tuner = static_cast<hcclTunerFuncs_v1_t*>(dlsym(handle, "hcclTunerPlugin_v1"));
82	    if (tuner == nullptr || tuner->init == nullptr || tuner->getCollInfo == nullptr) {
83	        HCCL_WARNING("[Tuner] dlsym hcclTunerPlugin_v1 failed or null function pointers, err[%s].", dlerror());
84	        dlclose(handle);
85	        g_loadStatus = LOAD_FAILED;
86	        return false;
87	    }
88	
89	    g_libHandle = handle;
90	    g_funcs = *tuner;
91	    g_funcs.structSize = sizeof(hcclTunerFuncs_v1_t);
92	    g_refCount = 1;
93	    g_loadStatus = LOAD_SUCCESS;
94	    HCCL_INFO("[Tuner] plugin loaded (v1).");
95	    return true;
96	}
97	
98	/* 从 TopoInfoWithNetLayerDetails 填充 hcclTunerCommInfo_t。 */
99	HcclResult BuildCommInfo(
100	    HcclComm comm, const TopoInfoWithNetLayerDetails* topoInfo, hcclTunerCommInfo_t& commInfo, char* commNameBuf,
101	    uint32_t bufLen)
102	{
103	    commInfo = {};
104	    if (topoInfo != nullptr) {
105	        commInfo.nRanks = topoInfo->userRankSize;
106	        commInfo.nServers = topoInfo->serverNum;
107	        const auto& layers = topoInfo->netLayerDetails;
108	        if (!layers.localNetInsSizeOfLayer.empty()) {
109	            commInfo.nNpusPerServer = layers.localNetInsSizeOfLayer[0];
110	        }
111	        if (layers.netInstNumOfLayer.size() > 1) {
112	            commInfo.nPods = layers.netInstNumOfLayer[1];
113	        }
114	        if (layers.netInstNumOfLayer.size() > 2) {
115	            commInfo.nSuperPods = layers.netInstNumOfLayer[2];
116	        }
117	    }
118	
119	    if (commNameBuf != nullptr && bufLen > 0) {
120	        commNameBuf[0] = '\0';
121	        HcclResult ret = HcclGetCommName(comm, commNameBuf);
122	        if (ret != HCCL_SUCCESS) {
123	            HCCL_WARNING("[Tuner] HcclGetCommName failed, ret[%d].", ret);
124	        }
125	        commInfo.commName = commNameBuf;
126	    }
127	
128	    void* bufferAddr = nullptr;
129	    uint64_t bufferSize = 0;
130	    HcclResult ret = HcclGetHcclBuffer(comm, &bufferAddr, &bufferSize);
131	    if (ret != HCCL_SUCCESS) {
132	        HCCL_WARNING("[Tuner] HcclGetHcclBuffer failed, ret[%d].", ret);
133	    }
134	    commInfo.bufferSize = bufferSize;
135	
136	    commInfo.structSize = sizeof(hcclTunerCommInfo_t);
137	    return HCCL_SUCCESS;
138	}
139	
140	/* 构造 hcclTunerHostFunctions_t。 */
141	void BuildHostFuncs(hcclTunerHostFunctions_t& hostFuncs)
142	{
143	    hostFuncs = {};
144	    hostFuncs.ctxCreate = TunerCtxCreate;
145	    hostFuncs.ctxGet = TunerCtxGet;
146	    hostFuncs.ctxDestroy = TunerCtxDestroy;
147	    hostFuncs.logFunction = TunerLogFunction;
148	    hostFuncs.structSize = sizeof(hcclTunerHostFunctions_t);
149	}
150	} /* namespace */
151	
152	bool HcclTunerIsLoaded()
153	{
154	    std::lock_guard<std::mutex> lock(g_tunerMutex);
155	    return g_loadStatus == LOAD_SUCCESS;
156	}
157	
158	HcclResult HcclTunerInit(HcclComm comm, const TopoInfoWithNetLayerDetails* topoInfo)
159	{
160	    /* 1. 加载插件（mutex 保护，首次 dlopen + dlsym + 版本校验） */
161	    hcclTunerFuncs_v1_t funcs = {};
162	    {
163	        std::lock_guard<std::mutex> lock(g_tunerMutex);
164	        if (!LoadPluginLocked()) {
165	            return HCCL_SUCCESS; /* 未配置或加载失败，no-op，回退 CostModel */
166	        }
167	        funcs = g_funcs; /* 锁内拷贝，避免 TOCTOU 竞态 */
168	    }
169	
170	    /* 2. 填充 commInfo（不加锁，每个 comm 独立） */
171	    hcclTunerCommInfo_t commInfo = {};
172	    char commNameBuf[TUNER_COMM_NAME_MAX_LENGTH] = {};
173	    HcclResult ret = BuildCommInfo(comm, topoInfo, commInfo, commNameBuf, sizeof(commNameBuf));
174	    if (ret != HCCL_SUCCESS) {
175	        HCCL_WARNING("[Tuner] BuildCommInfo failed, ret[%d].", ret);
176	        return HCCL_SUCCESS;
177	    }
178	
179	    /* 3. 构造 hostFuncs */
180	    hcclTunerHostFunctions_t hostFuncs = {};
181	    BuildHostFuncs(hostFuncs);
182	
183	    /* 4. 调用插件 init（使用锁内拷贝的 funcs 副本） */
184	    HCCL_INFO(
185	        "[HcclTunerInit] comm[%p] nRanks[%u] nServers[%u] nNpusPerServer[%u] commName[%s] bufferSize[%llu].", comm,
186	        commInfo.nRanks, commInfo.nServers, commInfo.nNpusPerServer,
187	        (commInfo.commName != nullptr) ? commInfo.commName : "?", commInfo.bufferSize);
188	    auto initStart = std::chrono::steady_clock::now();
189	    ret = funcs.init(comm, &commInfo, &hostFuncs);
190	    auto initMs
191	        = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - initStart).count();
192	    if (static_cast<uint64_t>(initMs) > TUNER_SLOW_INIT_THRESHOLD_MS) {
193	        HCCL_WARNING("[Tuner] plugin init took %lldms (threshold %llums).", initMs, TUNER_SLOW_INIT_THRESHOLD_MS);
194	    }
195	    if (ret != HCCL_SUCCESS) {
196	        HCCL_WARNING("[HcclTunerInit] plugin init failed, ret[%d], fall back to CostModel.", ret);
197	        return HCCL_SUCCESS;
198	    }
199	    HCCL_INFO("[HcclTunerInit] plugin init success, comm[%p].", comm);
200	    return HCCL_SUCCESS;
201	}
202	
203	HcclResult HcclTunerCallGetCollInfo(
204	    HcclComm comm, HcclCMDType cmdType, size_t nBytes, HcclDataType dataType, hcclTunerAlgoEntry_t* algoEntries,
205	    int algoCount, bool* modified)
206	{
207	    if (modified != nullptr) {
208	        *modified = false;
209	    }
210	    if (algoEntries == nullptr || algoCount <= 0) {
211	        return HCCL_SUCCESS;
212	    }
213	
214	    /* 插件未加载时 no-op；锁内拷贝 g_funcs 避免 TOCTOU 竞态 */
215	    hcclTunerFuncs_v1_t funcs = {};
216	    {
217	        std::lock_guard<std::mutex> lock(g_tunerMutex);
218	        if (g_loadStatus != LOAD_SUCCESS) {
219	            return HCCL_SUCCESS;
220	        }
221	        funcs = g_funcs;
222	    }
223	
224	    /* 不支持的操作类型跳过 */
225	    if (cmdType == HCCL_CMD_INVALID) {
226	        return HCCL_SUCCESS;
227	    }
228	
229	    hcclTunerCollInfo_t collInfo = {};
230	    collInfo.collType = cmdType;
