74	static HcclCMDType op_type_from_name(const char* name)
75	{
76	    if (name == nullptr) {
77	        return HCCL_CMD_INVALID;
78	    }
79	    if (strcmp(name, "allreduce") == 0)
80	        return HCCL_CMD_ALLREDUCE;
81	    if (strcmp(name, "allgather") == 0)
82	        return HCCL_CMD_ALLGATHER;
83	    if (strcmp(name, "broadcast") == 0)
84	        return HCCL_CMD_BROADCAST;
85	    if (strcmp(name, "reduce") == 0)
86	        return HCCL_CMD_REDUCE;
87	    if (strcmp(name, "reduce_scatter") == 0)
88	        return HCCL_CMD_REDUCE_SCATTER;
89	    if (strcmp(name, "scatter") == 0)
90	        return HCCL_CMD_SCATTER;
91	    if (strcmp(name, "alltoall") == 0)
92	        return HCCL_CMD_ALLTOALL;
93	    if (strcmp(name, "alltoallv") == 0)
94	        return HCCL_CMD_ALLTOALLV;
95	    return HCCL_CMD_INVALID;
96	}
