234	/* 第一遍：遍历 JSON 树，统计总规则数。返回总规则数，opSetCount 写入出参。 */
235	static int CountRules(const nlohmann::json& root, int* opSetCount)
236	{
237	    *opSetCount = 0;
238	    if (!root.is_object() || !root.contains("op_types") || !root["op_types"].is_object()) {
239	        return 0;
240	    }
241	    int total = 0;
242	    for (auto it = root["op_types"].begin(); it != root["op_types"].end(); ++it) {
243	        if (*opSetCount >= MAX_OP_TYPES) {
244	            break;
245	        }
246	        HcclCMDType opType = op_type_from_name(it.key().c_str());
247	        if (opType == HCCL_CMD_INVALID) {
248	            continue;
249	        }
250	        if (it.value().is_object() && it.value().contains("rules") && it.value()["rules"].is_array()) {
251	            total += (int)it.value()["rules"].size();
252	        }
253	        (*opSetCount)++;
254	    }
255	    return total;
256	}
