258	static void ParseMatchField(const nlohmann::json& matchObj, Rule* r, SchemaState* s)
259	{
260	    static const char* knownKeys[]
261	        = {"min_ranks",           "max_ranks",           "min_bytes",   "max_bytes",   "data_type", "comm_name",
262	           "min_npus_per_server", "max_npus_per_server", "min_servers", "max_servers", "min_pods",  "max_pods",
263	           "min_super_pods",      "max_super_pods",      "buffer_size"};
264	    static const int knownKeyCount = (int)(sizeof(knownKeys) / sizeof(knownKeys[0]));
265	    for (auto it = matchObj.begin(); it != matchObj.end(); ++it) {
266	        bool known = false;
267	        for (int k = 0; k < knownKeyCount; k++) {
268	            if (it.key() == knownKeys[k]) {
269	                known = true;
270	                break;
271	            }
272	        }
273	        if (!known) {
274	            SchemaWarn(s, "match", it.key().c_str());
275	        }
276	    }
277	    if (matchObj.contains("min_ranks")) {
278	        r->match.hasMinRanks = 1;
279	        r->match.minRanks = matchObj["min_ranks"].get<uint32_t>();
280	    }
281	    if (matchObj.contains("max_ranks")) {
282	        r->match.hasMaxRanks = 1;
283	        r->match.maxRanks = matchObj["max_ranks"].get<uint32_t>();
284	    }
285	    if (matchObj.contains("min_bytes")) {
286	        r->match.hasMinBytes = 1;
287	        r->match.minBytes = matchObj["min_bytes"].get<size_t>();
288	    }
289	    if (matchObj.contains("max_bytes")) {
290	        r->match.hasMaxBytes = 1;
291	        r->match.maxBytes = matchObj["max_bytes"].get<size_t>();
292	    }
293	    if (matchObj.contains("data_type")) {
294	        if (snprintf_s(
295	                r->match.dataType, sizeof(r->match.dataType), sizeof(r->match.dataType) - 1, "%s",
296	                matchObj["data_type"].get<std::string>().c_str())
297	            < 0) {
298	            r->match.dataType[0] = '\0';
299	        }
300	        r->match.dataTypeEnum = ParseDataType(r->match.dataType);
301	        r->match.hasDataType = 1;
302	    }
303	    if (matchObj.contains("comm_name")) {
304	        if (snprintf_s(
305	                r->match.commName, sizeof(r->match.commName), sizeof(r->match.commName) - 1, "%s",
306	                matchObj["comm_name"].get<std::string>().c_str())
307	            < 0) {
308	            r->match.commName[0] = '\0';
309	        }
310	        r->match.hasCommName = 1;
311	    }
312	    if (matchObj.contains("min_npus_per_server")) {
313	        r->match.hasMinNpusPerServer = 1;
314	        r->match.minNpusPerServer = matchObj["min_npus_per_server"].get<uint32_t>();
315	    }
316	    if (matchObj.contains("max_npus_per_server")) {
317	        r->match.hasMaxNpusPerServer = 1;
318	        r->match.maxNpusPerServer = matchObj["max_npus_per_server"].get<uint32_t>();
319	    }
320	    if (matchObj.contains("min_servers")) {
321	        r->match.hasMinServers = 1;
322	        r->match.minServers = matchObj["min_servers"].get<uint32_t>();
323	    }
324	    if (matchObj.contains("max_servers")) {
325	        r->match.hasMaxServers = 1;
326	        r->match.maxServers = matchObj["max_servers"].get<uint32_t>();
327	    }
328	    if (matchObj.contains("min_pods")) {
329	        r->match.hasMinPods = 1;
330	        r->match.minPods = matchObj["min_pods"].get<uint32_t>();
331	    }
332	    if (matchObj.contains("max_pods")) {
333	        r->match.hasMaxPods = 1;
334	        r->match.maxPods = matchObj["max_pods"].get<uint32_t>();
335	    }
336	    if (matchObj.contains("min_super_pods")) {
337	        r->match.hasMinSuperPods = 1;
338	        r->match.minSuperPods = matchObj["min_super_pods"].get<uint32_t>();
339	    }
340	    if (matchObj.contains("max_super_pods")) {
341	        r->match.hasMaxSuperPods = 1;
342	        r->match.maxSuperPods = matchObj["max_super_pods"].get<uint32_t>();
343	    }
344	    if (matchObj.contains("buffer_size")) {
345	        r->match.hasBufferSize = 1;
346	        r->match.bufferSize = matchObj["buffer_size"].get<uint64_t>();
347	    }
348	}
