350	static void ParseRule(const nlohmann::json& ruleObj, Rule* r, SchemaState* s)
351	{
352	    if (memset_s(r, sizeof(*r), 0, sizeof(*r)) != EOK) {
353	        SchemaError(s, "memset_s failed for rule");
354	        return;
355	    }
356	
357	    if (!ruleObj.is_object()) {
358	        SchemaError(s, "rule is not an object");
359	        return;
360	    }
361	
362	    // 检查 rule 层级未知字段（拼写检测）
363	    static const char* knownRuleKeys[] = {"match", "engine", "executor", "template", "cost", "args"};
364	    for (auto it = ruleObj.begin(); it != ruleObj.end(); ++it) {
365	        bool known = false;
366	        for (size_t k = 0; k < sizeof(knownRuleKeys) / sizeof(knownRuleKeys[0]); k++) {
367	            if (it.key() == knownRuleKeys[k]) {
368	                known = true;
369	                break;
370	            }
371	        }
372	        if (!known) {
373	            SchemaWarn(s, "rule", it.key().c_str());
374	        }
375	    }
376	
377	    if (ruleObj.contains("match") && ruleObj["match"].is_object()) {
378	        ParseMatchField(ruleObj["match"], r, s);
379	    } else {
380	        SchemaError(s, "rule missing required field 'match'");
381	    }
382	
383	    if (ruleObj.contains("engine")) {
384	        std::string buf = ruleObj["engine"].get<std::string>();
385	        if (!is_valid_engine(buf.c_str())) {
386	            SchemaError(s, "invalid engine '%s'", buf.c_str());
387	        } else {
388	            if (snprintf_s(r->engine, sizeof(r->engine), sizeof(r->engine) - 1, "%s", buf.c_str()) < 0) {
389	                r->engine[0] = '\0';
390	            }
391	        }
392	    }
393	    if (ruleObj.contains("executor")) {
394	        std::string buf = ruleObj["executor"].get<std::string>();
395	        if (!is_valid_executor(buf.c_str())) {
396	            SchemaError(s, "invalid executor '%s'", buf.c_str());
397	        } else {
398	            if (snprintf_s(r->executor, sizeof(r->executor), sizeof(r->executor) - 1, "%s", buf.c_str()) < 0) {
399	                r->executor[0] = '\0';
400	            }
401	        }
402	    }
403	    if (ruleObj.contains("template")) {
404	        std::string buf = ruleObj["template"].get<std::string>();
405	        if (!is_valid_template(buf.c_str())) {
406	            SchemaError(s, "invalid template '%s'", buf.c_str());
407	        } else {
408	            if (snprintf_s(r->templateName, sizeof(r->templateName), sizeof(r->templateName) - 1, "%s", buf.c_str())
409	                < 0) {
410	                r->templateName[0] = '\0';
411	            }
412	        }
413	    }
414	    if (ruleObj.contains("cost")) {
415	        r->cost = ruleObj["cost"].get<float>();
416	        r->hasCost = 1;
417	    }
418	
419	    /* 必填字段校验 */
420	    if (!r->hasCost) {
421	        SchemaError(s, "rule missing required field 'cost'");
422	    }
423	    if (!r->match.hasMinRanks) {
424	        SchemaError(s, "rule missing required field 'min_ranks'");
425	    }
426	    if (!r->match.hasMaxRanks) {
427	        SchemaError(s, "rule missing required field 'max_ranks'");
428	    }
429	    if (!r->match.hasMinBytes) {
430	        SchemaError(s, "rule missing required field 'min_bytes'");
431	    }
432	    if (!r->match.hasMaxBytes) {
433	        SchemaError(s, "rule missing required field 'max_bytes'");
434	    }
435	    if (r->engine[0] == '\0') {
436	        SchemaError(s, "rule missing required field 'engine'");
437	    }
438	    if (r->executor[0] == '\0') {
439	        SchemaError(s, "rule missing required field 'executor'");
440	    }
441	    if (r->templateName[0] == '\0') {
442	        SchemaError(s, "rule missing required field 'template'");
443	    }
444	    if (r->match.hasMinRanks && r->match.hasMaxRanks && r->match.minRanks > r->match.maxRanks) {
445	        SchemaError(s, "min_ranks(%u) > max_ranks(%u)", r->match.minRanks, r->match.maxRanks);
446	    }
447	    if (r->match.hasMinBytes && r->match.hasMaxBytes && r->match.minBytes > r->match.maxBytes) {
448	        SchemaError(s, "min_bytes(%zu) > max_bytes(%zu)", r->match.minBytes, r->match.maxBytes);
449	    }
450	}
