452	static void ParseOpRules(
453	    const nlohmann::json& opObj, StoredHeader* ctx, Rule* rules, int* curOffset, const char* opName, SchemaState* s)
454	{
455	    HcclCMDType opType = op_type_from_name(opName);
456	    if (opType == HCCL_CMD_INVALID) {
457	        SchemaError(s, "unknown op_type '%s'", opName);
458	        return;
459	    }
460	    if (ctx->opSetCount >= MAX_OP_TYPES) {
461	        SchemaError(s, "op_type count exceeds MAX_OP_TYPES(%d), '%s' skipped", MAX_OP_TYPES, opName);
462	        return;
463	    }
464	    OpSetDesc* desc = &ctx->opSets[ctx->opSetCount];
465	    desc->opType = opType;
466	    desc->ruleOffset = *curOffset;
467	    desc->ruleCount = 0;
468	
469	    if (!opObj.is_object() || !opObj.contains("rules") || !opObj["rules"].is_array()) {
470	        SchemaError(s, "op_type '%s' missing 'rules' array", opName);
471	        ctx->opSetCount++;
472	        return;
473	    }
474	
475	    for (const auto& ruleItem : opObj["rules"]) {
476	        if (desc->ruleCount < MAX_RULES_PER_OP) {
477	            ParseRule(ruleItem, &rules[*curOffset], s);
478	            (*curOffset)++;
479	            desc->ruleCount++;
480	        } else {
481	            SchemaError(
482	                s, "op_type '%s' rule count exceeds MAX_RULES_PER_OP(%d), extra rules skipped", opName,
483	                MAX_RULES_PER_OP);
484	            break;
485	        }
486	    }
487	
488	    if (desc->ruleCount == 0) {
489	        SchemaError(s, "op_type '%s' has no rules (minItems=1)", opName);
490	    }
491	    ctx->opSetCount++;
492	}
