494	static void ParseConfig(const nlohmann::json& root, StoredHeader* ctx, Rule* rules, int* curOffset, SchemaState* s)
495	{
496	    if (!root.is_object()) {
497	        SchemaError(s, "config root is not an object");
498	        return;
499	    }
500	
501	    if (root.contains("version")) {
502	        s->foundVersion = 1;
503	        int ver = root["version"].get<int>();
504	        if (ver != 1) {
505	            SchemaError(s, "version must be 1, got %d", ver);
506	        }
507	    } else {
508	        SchemaError(s, "missing required field 'version'");
509	    }
510	
511	    if (root.contains("op_types") && root["op_types"].is_object()) {
512	        s->foundOpTypes = 1;
513	        for (auto it = root["op_types"].begin(); it != root["op_types"].end(); ++it) {
514	            ParseOpRules(it.value(), ctx, rules, curOffset, it.key().c_str(), s);
515	        }
516	    } else {
517	        SchemaError(s, "missing required field 'op_types'");
518	    }
519	}
