521	/* ===== 配置文件加载（多级 fallback）===== */
522	static char* ReadFile(const char* path, size_t* outLen)
523	{
524	    FILE* fp = fopen(path, "r");
525	    if (fp == NULL) {
526	        return NULL;
527	    }
528	    (void)fseek(fp, 0, SEEK_END);
529	    long sz = ftell(fp);
530	    (void)fseek(fp, 0, SEEK_SET);
531	    if (sz <= 0 || sz > MAX_FILE_SIZE) {
532	        fclose(fp);
533	        return NULL;
534	    }
535	    char* buf = (char*)malloc((size_t)sz + 1);
536	    if (buf == NULL) {
537	        fclose(fp);
538	        return NULL;
539	    }
540	    size_t rd = fread(buf, 1, (size_t)sz, fp);
541	    fclose(fp);
542	    buf[rd] = '\0';
543	    *outLen = rd;
544	    return buf;
545	}
546	
547	/* ===== 规则匹配 ===== */
548	static int MatchRule(const Rule* r, const hcclTunerCollInfo_t* collInfo, const hcclTunerCommInfo_t* commInfo)
549	{
550	    if (r->match.hasMinRanks && commInfo->nRanks < r->match.minRanks) {
551	        return 0;
552	    }
553	    if (r->match.hasMaxRanks && commInfo->nRanks > r->match.maxRanks) {
554	        return 0;
555	    }
556	    if (r->match.hasMinBytes && collInfo->nBytes < r->match.minBytes) {
557	        return 0;
558	    }
559	    if (r->match.hasMaxBytes && collInfo->nBytes > r->match.maxBytes) {
560	        return 0;
561	    }
562	    if (r->match.hasDataType) {
563	        if (r->match.dataTypeEnum != collInfo->dataType) {
564	            return 0;
565	        }
566	    }
567	    if (r->match.hasCommName) {
568	        if (commInfo->commName == NULL || strstr(commInfo->commName, r->match.commName) == NULL) {
569	            return 0;
570	        }
571	    }
572	    if (r->match.hasMinNpusPerServer && commInfo->nNpusPerServer < r->match.minNpusPerServer) {
573	        return 0;
574	    }
575	    if (r->match.hasMaxNpusPerServer && commInfo->nNpusPerServer > r->match.maxNpusPerServer) {
576	        return 0;
577	    }
578	    if (r->match.hasMinServers && commInfo->nServers < r->match.minServers) {
579	        return 0;
580	    }
581	    if (r->match.hasMaxServers && commInfo->nServers > r->match.maxServers) {
582	        return 0;
583	    }
584	    if (r->match.hasMinPods && commInfo->nPods < r->match.minPods) {
585	        return 0;
586	    }
587	    if (r->match.hasMaxPods && commInfo->nPods > r->match.maxPods) {
588	        return 0;
589	    }
590	    if (r->match.hasMinSuperPods && commInfo->nSuperPods < r->match.minSuperPods) {
591	        return 0;
592	    }
593	    if (r->match.hasMaxSuperPods && commInfo->nSuperPods > r->match.maxSuperPods) {
594	        return 0;
595	    }
596	    if (r->match.hasBufferSize && commInfo->bufferSize != r->match.bufferSize) {
597	        return 0;
598	    }
599	    return 1;
600	}
601	
602	static void ApplyRule(const Rule* r, hcclTunerAlgoEntry_t* entries, int count)
603	{
604	    int modified = 0;
605	    for (int i = 0; i < count; i++) {
606	        if (r->engine[0] && (entries[i].engineName == NULL || strcmp(r->engine, entries[i].engineName) != 0))
607	            continue;
608	        if (r->executor[0] && (entries[i].executorName == NULL || strcmp(r->executor, entries[i].executorName) != 0))
609	            continue;
610	        if (r->templateName[0]
611	            && (entries[i].templateName == NULL || strcmp(r->templateName, entries[i].templateName) != 0))
612	            continue;
613	        if (entries[i].cost < 0.0f) {
614	            if (g_hostFuncsReady && g_hostFuncs.logFunction != NULL) {
615	                g_hostFuncs.logFunction(
616	                    HCCL_TUNER_LOG_WARN, __FILE__, __LINE__, "[TunerDFX] skip disabled: algName=%s cost=%.6f",
617	                    entries[i].algName ? entries[i].algName : "?", entries[i].cost);
618	            }
619	            continue;
620	        }
621	        float oldCost = entries[i].cost;
622	        entries[i].cost = r->hasCost ? r->cost : 0.0f;
623	        if (g_hostFuncsReady && g_hostFuncs.logFunction != NULL) {
624	            g_hostFuncs.logFunction(
625	                HCCL_TUNER_LOG_INFO, __FILE__, __LINE__,
626	                "[TunerDFX] modify: algName=%s engine=%s executor=%s template=%s cost %.6f -> %.6f",
627	                entries[i].algName ? entries[i].algName : "?", entries[i].engineName ? entries[i].engineName : "?",
628	                entries[i].executorName ? entries[i].executorName : "?",
629	                entries[i].templateName ? entries[i].templateName : "?", oldCost, entries[i].cost);
630	        }
631	        modified++;
632	    }
633	    if (modified == 0 && g_hostFuncsReady && g_hostFuncs.logFunction != NULL) {
634	        g_hostFuncs.logFunction(
635	            HCCL_TUNER_LOG_WARN, __FILE__, __LINE__,
636	            "[TunerDFX] rule matched but no entry modified: engine=%s executor=%s template=%s cost=%.6f",
637	            r->engine[0] ? r->engine : "*", r->executor[0] ? r->executor : "*",
638	            r->templateName[0] ? r->templateName : "*", r->hasCost ? r->cost : 0.0f);
639	    }
640	}
641	
642	/* ===== 插件接口实现 ===== */
643	static HcclResult MyInit(HcclComm comm, const hcclTunerCommInfo_t* commInfo, const hcclTunerHostFunctions_t* hostFuncs)
644	{
645	    if (commInfo == NULL || hostFuncs == NULL) {
646	        return HCCL_E_PTR;
647	    }
648	    /* hostFuncs 是函数表，全进程相同，存全局 */
649	    g_hostFuncs = *hostFuncs;
650	    g_hostFuncsReady = 1;
651	
652	    /* 1. 读文件 + 解析 JSON（临时内存树，不持久化） */
653	    const char* envPath = getenv("HCCL_TUNER_CONFIG_FILE");
654	    const char* paths[] = {envPath, "./hccl_tuner_config.json", "/etc/hccl/hccl_tuner_config.json"};
655	    char* content = NULL;
656	    const char* loadedPath = NULL;
657	    for (size_t i = 0; i < sizeof(paths) / sizeof(paths[0]); i++) {
658	        if (paths[i] == NULL || paths[i][0] == '\0') {
659	            continue;
660	        }
661	        size_t len = 0;
662	        content = ReadFile(paths[i], &len);
663	        if (content != NULL) {
664	            loadedPath = paths[i];
665	            break;
666	        }
667	        if (g_hostFuncsReady && g_hostFuncs.logFunction != NULL) {
668	            g_hostFuncs.logFunction(
669	                HCCL_TUNER_LOG_WARN, __FILE__, __LINE__, "tuner config '%s' not found%s", paths[i],
670	                (i == 0) ? ", falling back to default paths" : "");
671	        }
672	    }
673	    if (content == NULL) {
674	        if (g_hostFuncs.logFunction != NULL) {
675	            g_hostFuncs.logFunction(HCCL_TUNER_LOG_WARN, __FILE__, __LINE__, "no tuner config loaded, plugin inactive");
676	        }
677	        return HCCL_SUCCESS;
678	    }
679	
680	    nlohmann::json root = nlohmann::json::parse(content, nullptr, false);
681	    if (root.is_discarded()) {
682	        if (g_hostFuncs.logFunction != NULL) {
683	            g_hostFuncs.logFunction(HCCL_TUNER_LOG_WARN, __FILE__, __LINE__, "JSON parse failed for %s", loadedPath);
684	        }
685	        free(content);
686	        return HCCL_SUCCESS;
687	    }
688	    free(content);
689	
690	    /* 2. 第一遍：遍历 JSON 树计数规则数 */
691	    int opSetCount = 0;
692	    int totalRules = CountRules(root, &opSetCount);
693	    if (totalRules > MAX_TOTAL_RULES) {
694	        if (g_hostFuncs.logFunction != NULL) {
695	            g_hostFuncs.logFunction(
696	                HCCL_TUNER_LOG_WARN, __FILE__, __LINE__, "total rules %d exceeds MAX_TOTAL_RULES(%d), plugin inactive",
697	                totalRules, MAX_TOTAL_RULES);
698	        }
699	        return HCCL_SUCCESS;
700	    }
701	
702	    /* 3. ctxCreate 精确大小：Header + totalRules × Rule */
703	    uint64_t ctxSize = sizeof(StoredHeader) + (uint64_t)totalRules * sizeof(Rule);
704	    void* storedCtx = NULL;
705	    if (hostFuncs->ctxCreate(comm, "main", ctxSize, &storedCtx) != HCCL_SUCCESS || storedCtx == NULL) {
706	        if (g_hostFuncs.logFunction != NULL) {
707	            g_hostFuncs.logFunction(HCCL_TUNER_LOG_WARN, __FILE__, __LINE__, "ctxCreate failed, plugin inactive");
708	        }
709	        return HCCL_SUCCESS;
710	    }
711	    if (memset_s(storedCtx, (size_t)ctxSize, 0, (size_t)ctxSize) != EOK) {
712	        if (g_hostFuncs.logFunction != NULL) {
713	            g_hostFuncs.logFunction(HCCL_TUNER_LOG_WARN, __FILE__, __LINE__, "memset_s failed for storedCtx");
714	        }
715	        return HCCL_SUCCESS;
716	    }
717	    StoredHeader* ctx = (StoredHeader*)storedCtx;
718	    Rule* rules = GetRules(ctx);
719	
720	    /* 4. 第二遍：填充 Header + Rule[] */
721	    SchemaState schema = {};
722	    int curOffset = 0;
723	    try {
724	        ParseConfig(root, ctx, rules, &curOffset, &schema);
725	    } catch (const nlohmann::json::exception& e) {
726	        SchemaError(&schema, "JSON field access error: %s", e.what());
727	    }
728	    ctx->totalRuleCount = curOffset;
729	#ifdef HCCL_TUNER_TESTING
730	    g_lastSchema = schema;
731	#endif
732	    if (g_hostFuncsReady && g_hostFuncs.logFunction != NULL) {
733	        g_hostFuncs.logFunction(
734	            HCCL_TUNER_LOG_INFO, __FILE__, __LINE__,
735	            "tuner config loaded from %s, opSetCount=%d, totalRules=%d, schemaErrors=%d, schemaWarnings=%d", loadedPath,
736	            ctx->opSetCount, ctx->totalRuleCount, schema.errors, schema.warnings);
737	    }
738	    if (schema.errors > 0) {
739	        if (g_hostFuncsReady && g_hostFuncs.logFunction != NULL) {
740	            g_hostFuncs.logFunction(
741	                HCCL_TUNER_LOG_WARN, __FILE__, __LINE__,
742	                "Schema validation failed (%d errors), plugin will not intervene", schema.errors);
743	        }
744	        ctx->configValid = 0;
745	    } else {
746	        ctx->configValid = 1;
747	    }
748	
749	    /* 5. 拷贝 commInfo（commName 需拷贝到持久缓冲，init 返回后 commInfo 指针失效） */
750	    ctx->commInfo = *commInfo;
751	    if (commInfo->commName != NULL) {
752	        if (snprintf_s(
753	                ctx->commNameBuf, sizeof(ctx->commNameBuf), sizeof(ctx->commNameBuf) - 1, "%s", commInfo->commName)
754	            < 0) {
755	            ctx->commNameBuf[0] = '\0';
756	        }
757	        ctx->commInfo.commName = ctx->commNameBuf;
758	    }
759	    if (g_hostFuncs.logFunction != NULL) {
760	        g_hostFuncs.logFunction(
761	            HCCL_TUNER_LOG_INFO, __FILE__, __LINE__, "tuner init done, comm[%p] nRanks[%u] opSetCount[%d]", comm,
762	            commInfo->nRanks, ctx->opSetCount);
763	    }
764	    return HCCL_SUCCESS;
765	}
766	
767	static HcclResult MyGetCollInfo(
768	    HcclComm comm, const hcclTunerCollInfo_t* collInfo, hcclTunerAlgoEntry_t* entries, int count, int* matched)
769	{
770	    if (collInfo == NULL || entries == NULL || count <= 0 || matched == NULL) {
771	        return HCCL_E_PTR;
772	    }
773	    /* *matched 已被 HCCL 核心初始化为 0（未命中） */
774	    if (!g_hostFuncsReady || g_hostFuncs.ctxGet == NULL) {
775	        return HCCL_SUCCESS;
776	    }
777	    void* ctxPtr = NULL;
778	    uint64_t ctxSize = 0;
779	    if (g_hostFuncs.ctxGet(comm, "main", &ctxPtr, &ctxSize) != HCCL_SUCCESS || ctxPtr == NULL) {
780	        return HCCL_SUCCESS;
781	    }
782	    /* C17：校验 ctxGet 返回的 size，防止 engine bug 或版本不一致导致越界读 */
783	    if (ctxSize < sizeof(StoredHeader)) {
784	        if (g_hostFuncs.logFunction != NULL) {
785	            g_hostFuncs.logFunction(
786	                HCCL_TUNER_LOG_WARN, __FILE__, __LINE__, "ctxGet size %llu < expected %zu, skip intervention",
787	                (unsigned long long)ctxSize, sizeof(StoredHeader));
788	        }
789	        return HCCL_SUCCESS;
790	    }
791	    StoredHeader* ctx = (StoredHeader*)ctxPtr;
792	
793	    /* Schema 校验失败时，不干预算法选择 */
794	    if (!ctx->configValid) {
795	        return HCCL_SUCCESS;
796	    }
797	
798	    Rule* rules = GetRules(ctx);
799	    for (int i = 0; i < ctx->opSetCount; i++) {
800	        OpSetDesc* desc = &ctx->opSets[i];
801	        if (desc->opType != collInfo->collType) {
802	            continue;
803	        }
804	        for (int j = 0; j < desc->ruleCount; j++) { /* first-match-wins */
805	            Rule* r = &rules[desc->ruleOffset + j];
806	            if (MatchRule(r, collInfo, &ctx->commInfo)) {
807	                if (g_hostFuncsReady && g_hostFuncs.logFunction != NULL) {
808	                    g_hostFuncs.logFunction(
809	                        HCCL_TUNER_LOG_INFO, __FILE__, __LINE__,
810	                        "[TunerDFX] rule hit: opType=%d nBytes=%zu dataType=%d ruleIdx=%d/%d "
811	                        "engine=%s executor=%s template=%s cost=%.6f",
812	                        (int)collInfo->collType, collInfo->nBytes, (int)collInfo->dataType, j, desc->ruleCount,
813	                        r->engine[0] ? r->engine : "*", r->executor[0] ? r->executor : "*",
814	                        r->templateName[0] ? r->templateName : "*", r->hasCost ? r->cost : 0.0f);
815	                }
816	                ApplyRule(r, entries, count);
817	                *matched = 1; /* 命中，设标志 */
818	                return HCCL_SUCCESS;
819	            }
820	        }
821	    }
822	    if (g_hostFuncsReady && g_hostFuncs.logFunction != NULL) {
823	        g_hostFuncs.logFunction(
824	            HCCL_TUNER_LOG_WARN, __FILE__, __LINE__, "[TunerDFX] no rule matched: opType=%d nBytes=%zu dataType=%d",
825	            (int)collInfo->collType, collInfo->nBytes, (int)collInfo->dataType);
826	    }
827	    return HCCL_SUCCESS;
828	}
829	
830	/* ===== 插件函数表（V1，直接导出全局变量，核心通过 dlsym 获取）===== */
831	hcclTunerFuncs_v1_t hcclTunerPlugin_v1 = {MyInit, MyGetCollInfo, sizeof(hcclTunerFuncs_v1_t)};
832	
833	/* 供 test_plugin.c 通过 #include "../plugin.c" 方式单元测试 */
834	#ifdef HCCL_TUNER_TESTING
835	StoredHeader* TunerGetStoredCtx(HcclComm comm)
836	{
837	    if (!g_hostFuncsReady || g_hostFuncs.ctxGet == NULL) {
838	        return NULL;
839	    }
840	    void* ctxPtr = NULL;
841	    uint64_t ctxSize = 0;
842	    if (g_hostFuncs.ctxGet(comm, "main", &ctxPtr, &ctxSize) != HCCL_SUCCESS) {
843	        return NULL;
844	    }
845	    return (StoredHeader*)ctxPtr;
846	}
847	#endif
848

